/**
 * Help (the in-app wiki): one source for the Help screen, the agent's canvas_catalog help, and docs/help.md
 * (generated by `pnpm help:docs`). Installed extensions add their own pages from their manifest's `docs`.
 */
import { extensionDocsMarkdown, markdownText, type ExtensionDocs } from "../markdown";
import { corePages, WIKI_SECTIONS } from "./pages";
import type { WikiPage, WikiSectionId } from "./types";

export type { WikiPage, WikiSection, WikiSectionId } from "./types";
export { WIKI_SECTIONS } from "./pages";
export { ART, ART_BOX, type ArtItem, type ArtTone, type WikiArtId } from "./art";
export { EXAMPLE_ACTIONS, EXAMPLE_DOCS, EXAMPLE_EXTENSION, EXAMPLE_FILE, EXAMPLE_HTML } from "./tutorial";

export const wikiPages: readonly WikiPage[] = corePages;
export const EXTENSION_PAGE_PREFIX = "ext:";
export const HOME_PAGE = "start.lienzo";

/** An installed extension as a Help page. One without a guide still gets a page that says what it is. */
export type DocumentedExtension = { id: string; name: string; description?: string; icon?: string; permissions: readonly string[]; docs?: ExtensionDocs; actions?: readonly DocumentedAction[] };
type DocumentedAction = { name: string; description: string; input?: { properties?: Record<string, { type: string; description?: string }>; required?: readonly string[] } };
/** "For your agent": what the extension offers an agent through canvas_extension_run, one entry per action. */
export function actionsMarkdown(actions: readonly DocumentedAction[]): string {
  const item = (action: DocumentedAction) => {
    const args = Object.entries(action.input?.properties ?? {}).map(([key, schema]) => `\`${key}\`${action.input?.required?.includes(key) ? "" : " (optional)"}: ${schema.description ?? schema.type}`);
    return `- **${action.name}**: ${action.description}${args.length ? ` Takes ${args.join("; ")}.` : ""}`;
  };
  return ["## For your agent", "Your agent can use this extension itself: ask it in your chat. Each run is one step in History, marked (agent), that undoes like any other.", actions.map(item).join("\n")].join("\n\n");
}
export function extensionPage(extension: DocumentedExtension): WikiPage {
  const asks = extension.permissions.length ? `It asks to ${extension.permissions.map(p => p === "edit" ? "change the canvas" : p === "network" ? "load things from the internet" : p === "view" ? "move the view of the canvas" : p).join(" and ")}.` : "It only reads the Lienzo and changes the selection.";
  return { id: EXTENSION_PAGE_PREFIX + extension.id, section: "extensions", title: extension.name, icon: extension.icon ?? "Puzzle", art: "extension",
    summary: extension.description || "An installed extension.",
    purpose: `${extension.description ? extension.description + " " : ""}Open it from the + catalog, under Extensions. ${asks}`,
    body: [extension.docs ? extensionDocsMarkdown(extension.docs) : "", extension.actions?.length ? actionsMarkdown(extension.actions) : ""].filter(Boolean).join("\n\n") || undefined,
    related: ["ext.about", "ext.permissions"], keywords: `extension installed${extension.actions?.length ? " agent actions" : ""}` };
}
/** Every page: the core ones, then one per installed extension, after the other Extensions pages. */
export function allWikiPages(extensions: readonly DocumentedExtension[] = []): WikiPage[] {
  const installed = extensions.map(extensionPage), at = wikiPages.findIndex(p => p.section === "make");
  return at < 0 ? [...wikiPages, ...installed] : [...wikiPages.slice(0, at), ...installed, ...wikiPages.slice(at)];
}
export const getWikiPage = (id: string, pages: readonly WikiPage[] = wikiPages) => pages.find(page => page.id === id);
/** Sections that have pages, in order, with their pages. */
export function wikiOutline(pages: readonly WikiPage[]): { id: WikiSectionId; title: string; icon: string; pages: WikiPage[] }[] {
  return WIKI_SECTIONS.map(section => ({ ...section, pages: pages.filter(p => p.section === section.id) })).filter(s => s.pages.length);
}

/** The page that explains a block type, or the closest one. */
export function pageForBlockType(typeId: string | undefined, pages: readonly WikiPage[] = wikiPages): WikiPage | undefined {
  return typeId ? pages.find(page => page.blockTypes?.includes(typeId)) : undefined;
}
/** The page the "?" of the Properties panel opens for what is selected. */
export function pageForSelection(selection: { kind: "block"; typeId: string } | { kind: "frame"; sheet: boolean } | { kind: "link" } | { kind: "many" } | { kind: "extension"; id: string }): string {
  switch (selection.kind) {
    case "block": return pageForBlockType(selection.typeId)?.id ?? "text.card";
    case "frame": return selection.sheet ? "sheets.sheets" : "frames.frame";
    case "link": return "drawing.links";
    case "many": return "drawing.select";
    case "extension": return EXTENSION_PAGE_PREFIX + selection.id;
  }
}

const fold = (value: string) => value.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
/** All the words of a page, for search. */
export function pageText(page: WikiPage): string {
  return [page.title, page.summary, page.purpose, ...(page.byHand ?? []), ...(page.askAgent ?? []), ...(page.tips ?? []), page.keywords ?? "", page.body ? markdownText(page.body) : ""].join(" ");
}
/**
 * Pages matching every word of the query (accents and case ignored), best first: a word in the title is worth most,
 * then in the summary or keywords, then anywhere on the page.
 */
export function searchWiki(pages: readonly WikiPage[], query: string): WikiPage[] {
  const words = fold(query).split(/\s+/).filter(Boolean);
  if (!words.length) return [];
  const scored = pages.flatMap(page => {
    const title = fold(page.title), near = fold(`${page.summary} ${page.keywords ?? ""}`), all = fold(pageText(page));
    if (!words.every(w => all.includes(w))) return [];
    const score = words.reduce((sum, w) => sum + (title.startsWith(w) ? 12 : title.includes(w) ? 8 : near.includes(w) ? 4 : 1), 0);
    return [{ page, score }];
  });
  return scored.sort((a, b) => b.score - a.score || a.page.title.localeCompare(b.page.title)).map(s => s.page);
}

/** A page as Markdown: for the agent (canvas_catalog help) and for docs/help.md. `keysOf` names a shortcut's keys. */
export function wikiPageMarkdown(page: WikiPage, options: { keysOf?(shortcut: string): string | undefined; level?: 1 | 2 } = {}): string {
  const h = options.level === 2 ? "##" : "#", sub = h + "#", keys = page.shortcut ? options.keysOf?.(page.shortcut) : undefined;
  const list = (items: readonly string[], ordered = false) => items.map((item, i) => `${ordered ? `${i + 1}.` : "-"} ${item}`).join("\n");
  return [
    `${h} ${page.title}`, page.summary, page.purpose,
    keys ? `Shortcut: ${keys}` : "",
    page.byHand?.length ? `${sub} By hand\n\n${list(page.byHand, true)}` : "",
    page.askAgent?.length ? `${sub} Ask your agent\n\n${list(page.askAgent.map(prompt => `“${prompt}”`))}` : "",
    page.tips?.length ? `${sub} Tips\n\n${list(page.tips)}` : "",
    page.body ?? "",
  ].filter(Boolean).join("\n\n");
}
/** What the agent gets from canvas_catalog help without a page: the table of contents. */
export function wikiContents(pages: readonly WikiPage[] = wikiPages) {
  return wikiOutline(pages).map(section => ({ section: section.title, pages: section.pages.map(({ id, title, summary }) => ({ id, title, summary })) }));
}
